// @zeus-internal
"use client";

import {
  useRef,
  useState,
  type AnchorHTMLAttributes,
  type ButtonHTMLAttributes,
  type CSSProperties,
  type FocusEvent,
  type HTMLAttributes,
  type MouseEvent,
  type PointerEvent,
  type ReactNode,
  type Ref,
} from "react";

type ActionElement = HTMLAnchorElement | HTMLButtonElement;
export interface AnimationButtonProps
  extends Omit<HTMLAttributes<ActionElement>, "color" | "onClick"> {
  children?: ReactNode;
  /** Seconds; zero makes the state change immediate. */
  duration?: number;
  /** A CSS easing function. */
  easing?: string;
  background?: string;
  fill?: string;
  color?: string;
  hoverColor?: string;
  radius?: number | string;
  disabled?: boolean;
  href?: string;
  target?: AnchorHTMLAttributes<HTMLAnchorElement>["target"];
  rel?: string;
  download?: AnchorHTMLAttributes<HTMLAnchorElement>["download"];
  type?: ButtonHTMLAttributes<HTMLButtonElement>["type"];
  name?: string;
  value?: ButtonHTMLAttributes<HTMLButtonElement>["value"];
  form?: string;
  formAction?: ButtonHTMLAttributes<HTMLButtonElement>["formAction"];
  formMethod?: string;
  formNoValidate?: boolean;
  formTarget?: string;
  onClick?: (event: MouseEvent<ActionElement>) => void;
  onPress?: (event: MouseEvent<ActionElement>) => void;
  elementRef?: Ref<ActionElement>;
}

type SurfaceProps = AnimationButtonProps & {
  variant: string;
  variables?: CSSProperties;
  onEngage?: (element: ActionElement, event?: PointerEvent<ActionElement>) => void;
  onDisengage?: (element: ActionElement) => void;
  onTrack?: (element: ActionElement, event: PointerEvent<ActionElement>) => void;
};

export const buttonCss = `
:where(.z-anb-action){position:relative;display:inline-flex;align-items:center;justify-content:center;box-sizing:border-box;max-width:100%;min-height:54.4px;padding:18px 40px;border:0;border-radius:var(--z-anb-radius,9999px);background:var(--z-anb-background,#ff885e);color:var(--z-anb-color,#0a0a0a);font:500 16px/1.15 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;text-align:center;text-decoration:none;vertical-align:middle;cursor:pointer;isolation:isolate;-webkit-tap-highlight-color:transparent;touch-action:manipulation;transition:color var(--z-anb-duration,.8s) var(--z-anb-easing,cubic-bezier(.76,0,.24,1))}
.z-anb-action[data-active=true]{color:var(--z-anb-hover-color,var(--z-anb-color,#0a0a0a))}
.z-anb-action:focus-visible{outline:2px solid currentColor;outline-offset:5px}.z-anb-action[disabled],.z-anb-action[aria-disabled=true]{opacity:.45;cursor:not-allowed}.z-anb-label{position:relative;z-index:2;display:inline-block;overflow-wrap:anywhere}.z-anb-fill{position:absolute;inset:0;z-index:0;pointer-events:none;background:var(--z-anb-fill,#ff4200)}
@media(prefers-reduced-motion:reduce){.z-anb-action,.z-anb-action *{transition-duration:0s!important;animation:none!important}}
`;

export function buttonVariables({
  duration = 0.8,
  easing = "cubic-bezier(.76,0,.24,1)",
  background = "#ff885e",
  fill = "#ff4200",
  color = "#0a0a0a",
  hoverColor = color,
  radius = 9999,
}: AnimationButtonProps): CSSProperties {
  return {
    "--z-anb-duration": `${Math.max(0, duration)}s`,
    "--z-anb-easing": easing,
    "--z-anb-background": background,
    "--z-anb-fill": fill,
    "--z-anb-color": color,
    "--z-anb-hover-color": hoverColor,
    "--z-anb-radius": typeof radius === "number" ? `${Math.max(0, radius)}px` : radius,
  } as CSSProperties;
}

/** Shared native semantics only. Each public button owns its animation. */
export function ButtonSurface({
  variant,
  variables,
  children,
  className = "",
  style,
  disabled = false,
  href,
  target,
  rel,
  download,
  type = "button",
  name,
  value,
  form,
  formAction,
  formMethod,
  formNoValidate,
  formTarget,
  elementRef,
  onPress,
  onClick,
  onEngage,
  onDisengage,
  onTrack,
  onPointerEnter,
  onPointerLeave,
  onPointerMove,
  onPointerDown,
  onPointerUp,
  onPointerCancel,
  onFocus,
  onBlur,
  duration: _duration,
  easing: _easing,
  background: _background,
  fill: _fill,
  color: _color,
  hoverColor: _hoverColor,
  radius: _radius,
  ...native
}: SurfaceProps) {
  const [active, setActive] = useState(false);
  const hover = useRef(false),
    focus = useRef(false);
  const engage = (element: ActionElement, event?: PointerEvent<ActionElement>) => {
    if (disabled) return;
    setActive(true);
    onEngage?.(element, event);
  };
  const disengage = (element: ActionElement) => {
    if (hover.current || focus.current) return;
    setActive(false);
    onDisengage?.(element);
  };
  const shared = {
    ...native,
    ref: elementRef,
    className: `z-anb-action z-anb-${variant} ${className}`,
    style: { ...variables, ...style },
    "data-active": active && !disabled,
    onClick: (event: MouseEvent<ActionElement>) => {
      if (disabled) {
        event.preventDefault();
        return;
      }
      onClick?.(event);
      if (!event.defaultPrevented) onPress?.(event);
    },
    onPointerEnter: (event: PointerEvent<ActionElement>) => {
      onPointerEnter?.(event);
      if (event.pointerType !== "touch") {
        hover.current = true;
        engage(event.currentTarget, event);
      }
    },
    onPointerLeave: (event: PointerEvent<ActionElement>) => {
      onPointerLeave?.(event);
      hover.current = false;
      disengage(event.currentTarget);
    },
    onPointerMove: (event: PointerEvent<ActionElement>) => {
      onPointerMove?.(event);
      if (!disabled && event.pointerType !== "touch") onTrack?.(event.currentTarget, event);
    },
    onPointerDown: (event: PointerEvent<ActionElement>) => {
      onPointerDown?.(event);
      if (event.pointerType === "touch") engage(event.currentTarget, event);
    },
    onPointerUp: (event: PointerEvent<ActionElement>) => {
      onPointerUp?.(event);
      if (event.pointerType === "touch") disengage(event.currentTarget);
    },
    onPointerCancel: (event: PointerEvent<ActionElement>) => {
      onPointerCancel?.(event);
      hover.current = false;
      disengage(event.currentTarget);
    },
    onFocus: (event: FocusEvent<ActionElement>) => {
      onFocus?.(event);
      // Pointer clicks retain their native focus without pinning hover motion.
      focus.current = event.currentTarget.matches(":focus-visible");
      if (focus.current) engage(event.currentTarget);
    },
    onBlur: (event: FocusEvent<ActionElement>) => {
      onBlur?.(event);
      focus.current = false;
      disengage(event.currentTarget);
    },
  };
  return (
    <>
      <style>{buttonCss}</style>
      {href !== undefined ? (
        <a
          {...shared}
          ref={elementRef as Ref<HTMLAnchorElement>}
          href={disabled ? undefined : href}
          aria-disabled={disabled || undefined}
          tabIndex={disabled ? -1 : native.tabIndex}
          target={target}
          rel={rel ?? (target === "_blank" ? "noopener noreferrer" : undefined)}
          download={download}
        >
          {children}
        </a>
      ) : (
        <button
          {...shared}
          ref={elementRef as Ref<HTMLButtonElement>}
          disabled={disabled}
          type={type}
          name={name}
          value={value}
          form={form}
          formAction={formAction}
          formMethod={formMethod}
          formNoValidate={formNoValidate}
          formTarget={formTarget}
        >
          {children}
        </button>
      )}
    </>
  );
}

"use client";
import { useCallback, useEffect, useRef } from "react";
import { ButtonSurface, buttonVariables, type AnimationButtonProps } from "./button-shared";

export interface CurveFillButtonProps extends AnimationButtonProps {
  /** Depth of the curved leading edge, in percent of button size. */
  curvature?: number;
  direction?: "auto" | "left" | "right" | "top" | "bottom";
}
type Side = "left" | "right" | "top" | "bottom";
function waveEasing(value?: string): (progress: number) => number {
  if (!value) return (t) => (t === 1 ? 1 : 1 - 2 ** (-10 * t));
  if (value === "linear") return (t) => t;
  const aliases: Record<string, string> = {
    ease: ".25,.1,.25,1",
    "ease-in": ".42,0,1,1",
    "ease-out": "0,0,.58,1",
    "ease-in-out": ".42,0,.58,1",
  };
  const coordinates = (aliases[value] || value.match(/^cubic-bezier\(([^)]+)\)$/)?.[1])
    ?.split(",")
    .map(Number);
  if (coordinates?.length !== 4 || coordinates.some((n) => !Number.isFinite(n)))
    return (t) => (t === 1 ? 1 : 1 - 2 ** (-10 * t));
  const [x1, y1, x2, y2] = coordinates as [number, number, number, number];
  const cubic = (t: number, a: number, b: number) =>
    3 * (1 - t) ** 2 * t * a + 3 * (1 - t) * t ** 2 * b + t ** 3;
  return (progress) => {
    if (progress === 0 || progress === 1) return progress;
    let low = 0,
      high = 1;
    for (let i = 0; i < 14; i++) {
      const t = (low + high) / 2;
      if (cubic(t, x1, x2) < progress) low = t;
      else high = t;
    }
    return Math.max(0, Math.min(1, cubic((low + high) / 2, y1, y2)));
  };
}
const css = `.z-anb-curve{overflow:hidden;font-family:Arial,sans-serif}.z-anb-curve-svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:0}.z-anb-curve-fill{fill:var(--z-anb-fill)}`;

/** A curved wave rolls from the pointer's nearest edge and retreats on exit. */
export function CurveFillButton({
  children = "Discover Our New Collection",
  duration = 0.8,
  easing,
  curvature = 5,
  direction = "auto",
  ...props
}: CurveFillButtonProps) {
  const path = useRef<SVGPathElement>(null),
    frame = useRef(0),
    progress = useRef(0),
    destination = useRef(0),
    side = useRef<Side>("bottom");
  const draw = useCallback(
    (value: number) => {
      const edge = value * 100,
        bend = Math.max(0, curvature) * value;
      const d =
        side.current === "left"
          ? `M0 0 H${edge} Q${edge + bend} 50 ${edge} 100 H0 Z`
          : side.current === "right"
            ? `M100 0 H${100 - edge} Q${100 - edge - bend} 50 ${100 - edge} 100 H100 Z`
            : side.current === "top"
              ? `M0 0 V${edge} Q50 ${edge + bend} 100 ${edge} V0 Z`
              : `M0 100 V${100 - edge} Q50 ${100 - edge - bend} 100 ${100 - edge} V100 Z`;
      path.current?.setAttribute("d", d);
    },
    [curvature],
  );
  useEffect(() => {
    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)");
    const settle = () => {
      cancelAnimationFrame(frame.current);
      progress.current = destination.current;
      draw(progress.current);
    };
    const change = () => {
      if (reduced?.matches) settle();
    };
    if (props.disabled) {
      destination.current = 0;
      settle();
    }
    reduced?.addEventListener("change", change);
    return () => {
      reduced?.removeEventListener("change", change);
      cancelAnimationFrame(frame.current);
    };
  }, [props.disabled, draw]);
  const animate = (target: number) => {
    destination.current = target;
    cancelAnimationFrame(frame.current);
    if (duration <= 0 || window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches) {
      progress.current = target;
      draw(target);
      return;
    }
    const ease = waveEasing(easing);
    const start = performance.now(),
      from = progress.current;
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / (duration * 1000));
      const eased = ease(t);
      progress.current = from + (target - from) * eased;
      draw(progress.current);
      if (t < 1) frame.current = requestAnimationFrame(tick);
    };
    frame.current = requestAnimationFrame(tick);
  };
  return (
    <>
      <style>{css}</style>
      <ButtonSurface
        {...props}
        duration={duration}
        variant="curve"
        variables={buttonVariables({ ...props, duration, easing })}
        onEngage={(element, event) => {
          if (direction !== "auto") side.current = direction;
          else if (event) {
            const box = element.getBoundingClientRect(),
              x = event.clientX - box.left,
              y = event.clientY - box.top;
            const distances: [Side, number][] = [
              ["left", x],
              ["right", box.width - x],
              ["top", y],
              ["bottom", box.height - y],
            ];
            side.current = distances.sort((a, b) => a[1] - b[1])[0]![0];
          } else side.current = "bottom";
          element.setAttribute("data-direction", side.current);
          animate(1);
        }}
        onDisengage={() => animate(0)}
      >
        <svg
          className="z-anb-curve-svg"
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
          aria-hidden="true"
        >
          <path ref={path} className="z-anb-curve-fill" d="M0 100 H100 Z" />
        </svg>
        <span className="z-anb-label">{children}</span>
      </ButtonSurface>
    </>
  );
}
